41	/**
42	 * Base component for selection lists that provides common UI structure
43	 * and keyboard navigation logic via the useSelectionList hook.
44	 *
45	 * This component handles:
46	 * - Radio button indicators
47	 * - Item numbering
48	 * - Scrolling for long lists
49	 * - Color theming based on selection/disabled state
50	 * - Keyboard navigation and numeric selection
51	 *
52	 * Specific components should use this as a base and provide
53	 * their own renderItem implementation for custom content.
54	 */
55	export function BaseSelectionList<
56	  T,
57	  TItem extends SelectionListItem<T> = SelectionListItem<T>,
58	>({
59	  items,
60	  initialIndex = 0,
61	  onSelect,
62	  onHighlight,
63	  isFocused = true,
64	  showNumbers = true,
65	  showScrollArrows = false,
66	  maxItemsToShow = 10,
67	  wrapAround = true,
68	  focusKey,
69	  priority,
70	  selectedIndicator = '●',
71	  renderItem,
72	}: BaseSelectionListProps<T, TItem>): React.JSX.Element {
73	  const { activeIndex } = useSelectionList({
74	    items,
75	    initialIndex,
76	    onSelect,
77	    onHighlight,
78	    isFocused,
79	    showNumbers,
80	    wrapAround,
81	    focusKey,
82	    priority,
83	  });
84	
85	  const [scrollOffset, setScrollOffset] = useState(0);
86	
87	  // Derive the effective scroll offset during render to avoid "no-selection" flicker.
88	  // This ensures that the visibleItems calculation uses an offset that includes activeIndex.
89	  let effectiveScrollOffset = scrollOffset;
90	  if (activeIndex < effectiveScrollOffset) {
91	    effectiveScrollOffset = activeIndex;
92	  } else if (activeIndex >= effectiveScrollOffset + maxItemsToShow) {
93	    effectiveScrollOffset = Math.max(
94	      0,
95	      Math.min(activeIndex - maxItemsToShow + 1, items.length - maxItemsToShow),
96	    );
97	  }
98	
99	  // Synchronize state if it changed during derivation
100	  if (effectiveScrollOffset !== scrollOffset) {
101	    setScrollOffset(effectiveScrollOffset);
102	  }
103	
104	  const visibleItems = items.slice(
105	    effectiveScrollOffset,
106	    effectiveScrollOffset + maxItemsToShow,
107	  );
108	  const numberColumnWidth = String(items.length).length;
109	
110	  return (
111	    <Box flexDirection="column">
112	      {/* Use conditional coloring instead of conditional rendering */}
113	      {showScrollArrows && items.length > maxItemsToShow && (
114	        <Text
115	          color={
116	            effectiveScrollOffset > 0
117	              ? theme.text.primary
118	              : theme.text.secondary
119	          }
120	        >
121	          ▲
122	        </Text>
123	      )}
124	
125	      {visibleItems.map((item, index) => {
126	        const itemIndex = effectiveScrollOffset + index;
127	        const isSelected = activeIndex === itemIndex;
128	
129	        // Determine colors based on selection and disabled state
130	        let titleColor = theme.text.primary;
131	        let numberColor = theme.text.primary;
132	
133	        if (isSelected) {
134	          titleColor = theme.ui.focus;
135	          numberColor = theme.ui.focus;
136	        } else if (item.disabled) {
137	          titleColor = theme.text.secondary;
138	          numberColor = theme.text.secondary;
139	        }
140	
141	        if (!isFocused && !item.disabled) {
142	          numberColor = theme.text.secondary;
143	        }
144	
145	        if (!showNumbers) {
146	          numberColor = theme.text.secondary;
147	        }
148	
149	        const itemNumberText = `${String(itemIndex + 1).padStart(
150	          numberColumnWidth,
151	        )}.`;
152	
153	        return (
154	          <Box
155	            key={item.key}
156	            alignItems="flex-start"
157	            backgroundColor={isSelected ? theme.background.focus : undefined}
158	          >
159	            {/* Radio button indicator */}
160	            <Box minWidth={2} flexShrink={0}>
161	              <Text
162	                color={isSelected ? theme.ui.focus : theme.text.primary}
163	                aria-hidden
164	              >
165	                {isSelected ? selectedIndicator : ' '}
166	              </Text>
167	            </Box>
168	
169	            {/* Item number */}
170	            {showNumbers && !item.hideNumber && (
171	              <Box
172	                marginRight={1}
173	                flexShrink={0}
174	                minWidth={itemNumberText.length}
175	                aria-state={{ checked: isSelected }}
176	              >
177	                <Text color={numberColor}>{itemNumberText}</Text>
178	              </Box>
179	            )}
180	
181	            {/* Custom content via render prop */}
182	            <Box flexGrow={1}>
183	              {renderItem(item, {
184	                isSelected,
185	                titleColor,
186	                numberColor,
187	              })}
188	            </Box>
189	          </Box>
190	        );
191	      })}
192	
193	      {showScrollArrows && items.length > maxItemsToShow && (
194	        <Text
195	          color={
196	            effectiveScrollOffset + maxItemsToShow < items.length
197	              ? theme.text.primary
198	              : theme.text.secondary
199	          }
200	        >
201	          ▼
202	        </Text>
203	      )}
204	    </Box>
205	  );
206	}
