/**
 * A single file section within an inbox patch.
 */
export interface InboxPatchEntry {
  /** Target file path (relative to a skills directory) with git prefixes stripped. */
  filePath: string;
  /** Number of added lines across the section's hunks. */
  additions: number;
  /** Number of removed lines across the section's hunks. */
  deletions: number;
}

/**
 * Represents a proposed update to an already-installed skill, stored as a
 * unified diff (`.patch`) file in the extraction inbox.
 */
export interface InboxPatch {
  /** The `.patch` file name in the inbox. */
  fileName: string;
  /** Name of the skill this patch updates. */
  name: string;
  /** Per-file sections contained in the patch. */
  entries: InboxPatchEntry[];
  /** When the patch was extracted (ISO string), if known. */
  extractedAt?: string;
}

/**
 * Strips a leading git-style `a/` or `b/` prefix from a diff header path.
 * Leaves the special `/dev/null` sentinel untouched.
 */
function stripGitPrefix(filePath: string): string {
  if (filePath === '/dev/null') {
    return filePath;
  }
  if (filePath.startsWith('a/') || filePath.startsWith('b/')) {
    return filePath.slice(2);
  }
  return filePath;
}

/**
 * Returns the target path for a parsed patch section (prefer the "new" file),
 * with git-style prefixes stripped. Returns undefined if the section has no
 * usable file header.
 */
function getSectionTargetPath(
  section: Diff.ParsedDiff,
): string | undefined {
  const rawPath =
    section.newFileName && section.newFileName !== '/dev/null'
      ? section.newFileName
      : section.oldFileName;
  if (!rawPath) {
    return undefined;
  }
  const stripped = stripGitPrefix(rawPath);
  if (!stripped || stripped === '/dev/null') {
    return undefined;
  }
  return stripped;
}

/**
 * Parses a unified diff into structured inbox-patch entries. Returns an empty
 * array when the content is not a valid, non-empty patch.
 */
function parsePatchEntries(content: string): InboxPatchEntry[] {
  let sections: Diff.ParsedDiff[];
  try {
    sections = Diff.parsePatch(content);
  } catch {
    return [];
  }

  const entries: InboxPatchEntry[] = [];
  for (const section of sections) {
    const filePath = getSectionTargetPath(section);
    if (!filePath) continue;
    if (!section.hunks || section.hunks.length === 0) continue;

    let additions = 0;
    let deletions = 0;
    for (const hunk of section.hunks) {
      for (const line of hunk.lines) {
        if (line.startsWith('+')) additions++;
        else if (line.startsWith('-')) deletions++;
      }
    }
    entries.push({ filePath, additions, deletions });
  }

  return entries;
}

/**
 * Derives the skill name a patch targets. Uses the top-level directory of the
 * first entry's path (e.g. `my-skill/SKILL.md` → `my-skill`); falls back to the
 * patch file name without its `.patch` suffix.
 */
function derivePatchName(
  fileName: string,
  entries: InboxPatchEntry[],
): string {
  const firstPath = entries[0]?.filePath;
  if (firstPath) {
