/**
 * Validates a patch file name: it must be a bare file name (no path separators
 * or traversal segments).
 */
function isValidInboxPatchFileName(fileName: string): boolean {
  return (
    fileName.length > 0 &&
    fileName !== '.' &&
    fileName !== '..' &&
    !fileName.includes('/') &&
    !fileName.includes('\\')
  );
}

/**
 * Scans the skill extraction inbox for `.patch` files and returns structured
 * data for each valid one.
 */
export async function listInboxPatches(config: Config): Promise<InboxPatch[]> {
  const skillsDir = config.storage.getProjectSkillsMemoryDir();

  let entries: Array<import('node:fs').Dirent>;
  try {
    entries = await fs.readdir(skillsDir, { withFileTypes: true });
  } catch {
    return [];
  }

  const patchFiles = entries.filter(
    (e) => e.isFile() && e.name.endsWith('.patch'),
  );
  if (patchFiles.length === 0) {
    return [];
  }

  // Load extraction state to map patch file names → extraction dates.
  const memoryDir = config.storage.getProjectMemoryTempDir();
  const statePath = path.join(memoryDir, '.extraction-state.json');
  const state = await readExtractionState(statePath);
  const patchDateMap = new Map<string, string>();
  for (const run of state.runs) {
    for (const patchName of run.patchesCreated ?? []) {
      patchDateMap.set(patchName, run.runAt);
    }
  }

  const patches: InboxPatch[] = [];
  for (const file of patchFiles) {
    const patchPath = path.join(skillsDir, file.name);
    let content: string;
    try {
      content = await fs.readFile(patchPath, 'utf-8');
    } catch {
      continue;
    }

    const patchEntries = parsePatchEntries(content);
    if (patchEntries.length === 0) {
      // Not a valid patch — skip it.
      continue;
    }

    patches.push({
      fileName: file.name,
      name: derivePatchName(file.name, patchEntries),
      entries: patchEntries,
      extractedAt: patchDateMap.get(file.name),
    });
  }

  return patches;
}

