/** A single row in the inbox list: either a new skill or a skill update. */
type InboxItem =
  | { kind: 'skill'; skill: InboxSkill }
  | { kind: 'patch'; patch: InboxPatch };

function inboxItemKey(item: InboxItem): string {
  return item.kind === 'skill'
    ? `skill:${item.skill.dirName}`
    : `patch:${item.patch.fileName}`;
}

function formatDate(isoString: string): string {
  try {
    const date = new Date(isoString);
    return date.toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return isoString;
  }
}

function formatPatchSummary(patch: InboxPatch): string {
  const additions = patch.entries.reduce((sum, e) => sum + e.additions, 0);
  const deletions = patch.entries.reduce((sum, e) => sum + e.deletions, 0);
  const fileCount = patch.entries.length;
  const fileLabel = `${fileCount} file${fileCount !== 1 ? 's' : ''}`;
  return `${fileLabel}, +${additions} -${deletions}`;
}

